	('0519e42f-a8c9-46d3-bb0e-d133ff72df45', NULL, 'lifecycle', 'trial_unconverted_days', 'Read-only days after a trial that did not convert, then deletion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', 30, 'days', false, 'draft', 'ASSUMPTION in the retention schedule 2.4.', NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('5c6a71d6-f259-41f3-9e07-c75eedf41c7c', NULL, 'lifecycle', 'person_request_response_days', 'Working response period for a data-subject request.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', 30, 'days', false, 'draft', 'CONFIRM against the DPDP Rules.', NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
